<h1>Website data</h1><p>Update your website using these fields. Save a section to publish its changes.</p><nav class="section-shortcuts"><?php foreach(db()->query('SELECT name FROM content') as $section): ?><a href="#edit-<?= e($section['name']) ?>"><?= e(ucwords($section['name'])) ?></a><?php endforeach ?></nav>
<?php foreach(db()->query('SELECT name FROM content') as $section): ?><details class="editor-panel data-section" id="edit-<?= e($section['name']) ?>"><summary><?= e(ucwords($section['name'])) ?> <span>Update details and photos</span></summary><form method="post" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="action" value="site-data"><input type="hidden" name="section" value="<?= e($section['name']) ?>"><div class="data-fields"><?php $q=db()->prepare('SELECT * FROM site_fields WHERE section=? ORDER BY id');$q->execute([$section['name']]);foreach($q as $field): ?><div class="data-field <?= in_array($field['kind'],['image','background'])?'photo-field':'' ?>"><label><?= e($field['label']) ?><?php if($field['kind']==='text' && strlen($field['value'])>110): ?><textarea name="field[<?= (int)$field['id'] ?>]" rows="4" maxlength="10000"><?= e($field['value']) ?></textarea><?php else: ?><input <?= $field['kind']==='money'?'type="number" min="0" max="1000000" step="0.01"':'type="text"' ?> name="field[<?= (int)$field['id'] ?>]" value="<?= e($field['value']) ?>" maxlength="10000"><?php endif ?></label><?php if(in_array($field['kind'],['image','background'])): ?><img class="admin-photo" src="<?= e($field['value']) ?>" alt="Current photo" loading="lazy"><label>Upload a replacement photo<input type="file" name="photo[<?= (int)$field['id'] ?>]" accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG or WebP, up to 5 MB. Uploading replaces the photo URL.</small><?php endif ?></div><?php endforeach ?></div><div class="save-bar"><button class="button">Save <?= e($section['name']) ?> changes</button><a href="index.php#<?= e($section['name']) ?>" target="_blank" rel="noopener">View this section</a></div></form></details><?php endforeach ?>
